previewCss:
.darma-loader-darma-b15-frost-crystal { --accent: var(--loader-color, #38bdf8); --accent-2: var(--loader-secondary-color, #e0f2fe); width: var(--loader-size, 112px); height: var(--loader-size, 112px); position: relative; }
.darma-loader-darma-b15-frost-crystal span { position: absolute; left: 48.5%; top: 8%; width: 3%; height: 42%; border-radius: 2px; transform-origin: 50% 100%; background: linear-gradient(var(--accent-2), var(--accent)); animation: darma-loader-darma-b15-frost-crystal-frost-arm calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite; }
.darma-loader-darma-b15-frost-crystal span::before { content: ''; position: absolute; left: -240%; top: 34%; width: 260%; height: 12%; border-radius: 2px; background: var(--accent); transform: rotate(38deg); transform-origin: 100% 50%; }
.darma-loader-darma-b15-frost-crystal span::after { content: ''; position: absolute; left: 80%; top: 34%; width: 260%; height: 12%; border-radius: 2px; background: var(--accent); transform: rotate(-38deg); transform-origin: 0 50%; }
.darma-loader-darma-b15-frost-crystal span:nth-of-type(1) { --rot: 0deg; }
.darma-loader-darma-b15-frost-crystal span:nth-of-type(2) { --rot: 60deg; animation-delay: calc(var(--loader-speed, 1s) * .12); }
.darma-loader-darma-b15-frost-crystal span:nth-of-type(3) { --rot: 120deg; animation-delay: calc(var(--loader-speed, 1s) * .24); }
.darma-loader-darma-b15-frost-crystal span:nth-of-type(4) { --rot: 180deg; animation-delay: calc(var(--loader-speed, 1s) * .36); }
.darma-loader-darma-b15-frost-crystal span:nth-of-type(5) { --rot: 240deg; animation-delay: calc(var(--loader-speed, 1s) * .48); }
.darma-loader-darma-b15-frost-crystal span:nth-of-type(6) { --rot: 300deg; animation-delay: calc(var(--loader-speed, 1s) * .6); }
.darma-loader-darma-b15-frost-crystal .darma-loader-darma-b15-frost-crystal__core { position: absolute; left: 44%; top: 44%; width: 12%; height: 12%; border-radius: 50%; background: var(--accent-2); animation: darma-loader-darma-b15-frost-crystal-frost-core calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite; }
@keyframes darma-loader-darma-b15-frost-crystal-frost-arm { 0%, 6% { transform: rotate(var(--rot, 0deg)) scaleY(0); opacity: 0; } 34%, 66% { transform: rotate(var(--rot, 0deg)) scaleY(1); opacity: 1; } 94%, 100% { transform: rotate(var(--rot, 0deg)) scaleY(0); opacity: 0; } }
@keyframes darma-loader-darma-b15-frost-crystal-frost-core { 0%, 100% { transform: scale(.5); opacity: .4; } 40%, 66% { transform: scale(1); opacity: 1; } }

